$grade_titles = [1 => 'کلاس اول دبستان', 2 => 'کلاس دوم دبستان', 3 => 'کلاس سوم دبستان', 4 => 'کلاس چهارم دبستان', 5 => 'کلاس پنجم دبستان', 6 => 'کلاس ششم دبستان'];
$joyo_by_kanji = [];
foreach ($joyo_kanji as $row) {
    $joyo_by_kanji[$row[0]] = $row;
}
$school_grade_categories = [];
foreach ($official_grade_kanji as $grade => $characters) {
    $items = [];
    foreach (preg_split('//u', $characters, -1, PREG_SPLIT_NO_EMPTY) as $character) {
        $row = $joyo_by_kanji[$character] ?? [$character, '', '', '', ''];
        $items[] = [
            'k' => $character,
            'kun' => $row[1],
            'on' => $row[2],
            'mean' => $row[3],
            'mean_en' => $row[4],
        ];
    }
    $school_grade_categories[] = [
        'title' => $grade_titles[$grade],
        'title_en' => 'Grade ' . $grade . ' School Kanji',
        'icon' => 'fa-child',
        'desc' => 'فهرست رسمی کانجی‌های تخصیص‌یافته به پایهٔ ' . $grade . ' دبستان در ژاپن، بر اساس جدول وزارت آموزش ژاپن (MEXT).',
        'school_grade' => $grade,
        'items' => $items,
    ];
}

