    $character = $item['k'];
    $examples = [];
    foreach (array_merge($school_grade_examples_by_kanji[$character] ?? [], $school_grade6_fallback_examples[$character] ?? []) as $example) {
        if (isset($example[0], $example[1], $example[2]) && strpos($example[0], $character) !== false) {
            $examples[$example[0]] = $example;
        }
        if (count($examples) >= 3) {
            break;
        }
    }
    $item['ex'] = array_values($examples);
}
unset($item);
for ($gradeIndex = 0; $gradeIndex < 5; $gradeIndex++) {
    foreach ($school_grade_categories[$gradeIndex]['items'] as &$item) {
