            if (isset($example[0], $example[1], $example[2]) && strpos($example[0], $character) !== false) {
                $examples[$example[0]] = $example;
            }
            if (count($examples) >= 3) {
                break;
            }
        }
        $item['ex'] = array_values($examples);
    }
