if (isset($school_grade2_5_data['value']) && is_array($school_grade2_5_data['value'])) { $school_grade2_5_data = $school_grade2_5_data['value']; }
$school_grade2_5_map = [];
foreach ($school_grade2_5_data ?: [] as $gradeData) foreach ($gradeData['rows'] ?? [] as $row) $school_grade2_5_map[$row['kanji']] = $row['examples'];
$school_grade2_5_map['区'] = [['区役所', 'くやくしょ', 'شهرداری منطقه'], ['区域', 'くいき', 'منطقه'], ['地区', 'ちく', 'ناحیه']];
$school_grade2_5_map['府'] = [['府県', 'ふけん', 'استان‌های ژاپن'], ['大阪府', 'おおさかふ', 'استان اوساکا'], ['京都府', 'きょうとふ', 'استان کیوتو']];
foreach ($school_grade_categories as &$category) {
    $grade = $category['school_grade'] ?? 0;
    if ($grade < 2 || $grade > 5) continue;
    foreach ($category['items'] as &$item) if (empty($item['ex']) && isset($school_grade2_5_map[$item['k']])) $item['ex'] = $school_grade2_5_map[$item['k']];
    unset($item);
}
unset($category);
